d<-source_tables$Fig4E$data[region=='EXON'];st<-source_tables$Fig4E$statistics[region=='EXON'];register('Fig4E',d,st,function()ggplot(d,aes(mmse_observed_min,probability))+geom_point(colour='#00A087',size=1.3,alpha=.7)+labs(x='Concurrent observed MMSE',y='EXON held-out probability',subtitle=sprintf('n=%d; rho=%.3f; P=%s',st$n,st$rho,fmtp(st$P)))+scale_y_continuous(limits=c(0,1),breaks=c(0,.5,1))+theme_pub(),'The primary EXON source-model held-out probability versus concurrent observed MMSE in the 100 disease participants. Subtitle gives actual n and two-sided Spearman rho/P. Adjusted effects and complete four-region results are supplied; this is cohort characterization, not independent clinical validation.','主要EXON来源模型折外概率与100例疾病参与者同期实测MMSE。标实际n及双侧Spearman rho/P。调整后及完整四区域结果随图，不属于独立临床验证。');participant_overrides$Fig4E<-d[,.(sample_id)]

